    Triangle triangle = *fit;
    CDT::Vertex_handle v = triangle.vertex(0);
    const CGALPoint p1 = v->point();
    v = triangle.vertex(1);
    const CGALPoint p2 = v->point();
    v = triangle.vertex(2);
    const CGALPoint p3 = v->point();

    result.push_back(Point2d(p1.x(), p1.y()));
    result.push_back(Point2d(p2.x(), p2.y()));
    result.push_back(Point2d(p3.x(), p3.y()));
}
return result;

